      }
      let issue;
      if(existing.length===1)issue=validateIssue(existing[0],this.client.repository);
      else {
        // タグの確認は読み取りだけで、作成要求を送る前に済ませる。失敗したときは、Issueを作らない。
        const labels=await this.categoryNames(row.report_id);
